entries[316847] = { ["name"] = "Adaptive Membran", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchützt ein Ziel mit einem Schild, der 12 Sek. lang Schaden absorbiert. Solange der Schild bestehen bleibt, ist das Ziel immun gegen Kontrollverlusteffekte und kann nicht unter 60% seiner normalen Bewegungsgeschwindigkeit verlangsamt werden.\n\nWenn der Schild vor Ablauf zerstört wird, wird sämtlicher abgefangener Schaden des Schilds dem Ziel zugefügt. Zusätzlich wird ' Fragment des Verstandes ' ausgelöst." }
entries[316848] = { ["name"] = "Adaptive Membran", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchützt ein Ziel mit einem Schild, der 12 Sek. lang Schaden absorbiert. Solange der Schild bestehen bleibt, ist die erhaltene Heilung des Ziels um 75% verringert und es ist immun gegen Kontrollverlust- und Unterbrechungseffekte und kann nicht unter 100% seiner normalen Bewegungsgeschwindigkeit verlangsamt werden.\n\nWenn der Schild vor Ablauf zerstört wird, wird sämtlicher abgefangener Schaden des Schilds dem Ziel zugefügt. Zusätzlich wird ' Verstandssplitter ' oder ' Fragment des Verstandes ' ausgelöst." }
