entries[317066] = { ["name"] = "Gedanken ernten", ["text"] = "Wirken in 5 sek.\nErntet die Gedanken von Spielercharakteren in der Nähe und fügt so allen Spielercharakteren innerhalb von 15 Metern 11238 Schattenschaden zu. Dabei wird außerdem 250 geistige Gesundheit anteilig von allen getroffenen Spielercharakteren entzogen.\n\nWenn 'Gedanken ernten' nicht mindestens 5 Spielercharaktere trifft, wird stattdessen allen Spielercharakteren 100 geistige Gesundheit entzogen." }
entries[317067] = { ["name"] = "Vorräte der Wüstenwanderer", ["text"] = "Sofort\nStellt im Verlauf von 10 Sek. 100% Gesundheit und Mana wieder her. Das Erleiden von Schaden entfernt den Effekt.\nAufgrund relevanter Kenntnisse zur Nahrungssuche in Zandalar, Kul Tiras, dem Tal der Ewigen Blüten, Uldum und Silithus werden Gesundheit und Mana an diesen Orten sofort wiederhergestellt." }
