entries[317072] = { ["name"] = "'Hinrichten' erlernen", ["text"] = "20 zu 40 Wut Nahkampfreichweite\nSofort 6 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nVersucht, einen verwundeten Gegner zu erledigen, und verursacht [(321.057% der Angriffskraft)% + (321.057% der Angriffskraft)%] körperlichen Schaden. Kann nur gegen Gegner mit weniger als 20% Gesundheit eingesetzt werden." }
entries[317073] = { ["name"] = "Hinrichten", ["text"] = "Sofort\nVersucht, einen Gegner zu erledigen. Verursacht bis zu [2.0 * (252.214% der Angriffskraft)] körperlichen Schaden basierend auf der verbrauchten Wut. Kann nur gegen Gegner mit weniger als 20% Gesundheit eingesetzt werden. [ Verbessertes Hinrichten : Wenn Euer Gegner überlebt, werden 10% der verbrauchten Wut zurückerstattet ]" }
entries[317075] = { ["name"] = "Sündhaftes Brandzeichen", ["text"] = "100 Meter Reichweite\nSofort\nBrandmarkt einen Gegner mit dem Zeichen der Venthyr, das sein Nahkampfangriffstempo um 30% und sein Zaubertempo um 30% verringert. Verursacht außerdem im Verlauf von 8 Sek. (338% der Angriffskraft) Schattenschaden.\n\nBeim Aktivieren von 'Metamorphose' werden alle Gegner in der Nähe mit 'Sündhaftes Brandzeichen' belegt." }
