entries[317102] = { ["name"] = "Seelenpein hervorrufen", ["text"] = "Wirken in 2 sek.\nN'Zoth dringt in den Verstand der Spielercharaktere ein und beschwört ihre finstersten Gedanken, was ihnen 8 Sek. lang alle 5.2 Sek. 13289 Schattenschaden zufügt.\n\nBeim Ablauf hinterlässt 'Seelenpein hervorrufen' eine Lache der Seelenpein, die nach ihrem Erscheinen für kurze Zeit wächst.\n\nJedes Mal, wenn N'Zoth der Verderber 'Seelenpein hervorrufen' einsetzt, wachsen alle bestehenden Lachen weiter an." }
